import{_ as t,o,c as a,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const m=JSON.parse('{"title":"Mobile Pro VisionCamera Capture, Offline-Resilient S3 Multipart Sync & Task Take Promotion","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/08-mobile-application/mobile-creator-upload/spec.md","filePath":"feature/modules/08-mobile-application/mobile-creator-upload/spec.md"}'),i={name:"feature/modules/08-mobile-application/mobile-creator-upload/spec.md"};function n(s,e,c,l,d,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="mobile-pro-visioncamera-capture-offline-resilient-s3-multipart-sync-task-take-promotion" tabindex="-1">Mobile Pro VisionCamera Capture, Offline-Resilient S3 Multipart Sync &amp; Task Take Promotion <a class="header-anchor" href="#mobile-pro-visioncamera-capture-offline-resilient-s3-multipart-sync-task-take-promotion" aria-label="Permalink to &quot;Mobile Pro VisionCamera Capture, Offline-Resilient S3 Multipart Sync &amp; Task Take Promotion&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>mobile-creator-upload</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>08-mobile-application</code> — BrandHub Mobile Application (Expo SDK 58 / React Native 0.88)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>mobile-creator-upload</code>, <code>mobile-video-task-sync</code>, <code>mobile-native-enhancements (OfflineBanner &amp; Haptics)</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/05-content-task-workflow/README.html">3.6 Content &amp; Workflow — Material Repository &amp; Task Content</a> (<code>3.6.11–3.6.16</code>, <code>3.6.4</code>)</td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Deliver BrandHub Mobile&#39;s flagship on-site production capability: <strong>Cinema-Style Native Camera Capture</strong> (<code>react-native-vision-camera</code> 5.2.4 with real hardware FPS, Shutter, ISO, WB, EV, Torch, Stabilization &amp; Teleprompter script overlay), <strong>Automatic Offline-Resilient S3 Multipart Task Upload Queue</strong> (<code>mediaSyncService.ts</code> + Wi-Fi-only toggle + HEIC-&gt;JPEG conversion), and <strong>Creator Take-to-Draft Promotion</strong> synced directly to Web Task Detail.</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As an on-site <code>Creator</code>, I want to shoot vertical/horizontal takes using real hardware camera controls (<code>CameraRecordScreen.tsx</code>) or pick gallery clips, have takes auto-upload in the background/foreground queue (resuming automatically after offline drops), and promote the best take into the Task draft for <code>Manager</code> review.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Pro Hardware Camera Deck (<code>CameraRecordScreen.tsx</code>, <code>mobile-video-task-sync</code> AC-12..13):</strong> Built on <code>react-native-vision-camera</code> 5.2.4 (<code>CameraBottomDeck.tsx</code>, <code>CameraDrawerAndRail.tsx</code>, <code>CameraOverlays.tsx</code>, <code>nativeCameraGuard.ts</code>). Exposes real hardware-verified FPS, resolution, stabilization, EV exposure bias, torch, zoom, and capability-gated manual Shutter &amp; White Balance Kelvin sliders (gracefully falling back to <code>CameraUnavailableScreen.tsx</code> on simulators/unsupported devices; zero fake ND/zebra/audio meters).</li><li><strong>Offline-Resilient Auto-Upload Queue (<code>mediaSyncService.ts</code>, <code>uploadService.ts</code>):</strong> Captured or gallery-picked files (<code>.mp4</code> <code>isom</code>/<code>mp42</code>, <code>.mov</code> <code>video/quicktime</code>, <code>JPEG/PNG/WebP</code>, plus automatic on-device <code>HEIC -&gt; JPEG</code> via <code>expo-image-manipulator</code>) enqueue immediately, persist across app restarts, pause cleanly with <code>OfflineBanner.tsx</code> (<code>@react-native-community/netinfo</code>) or optional &#39;Wi-Fi Only&#39; toggle, auto-renew expired S3 upload sessions (<code>POST /materials/upload-session[/multipart]</code>), and never auto-submit the Task for approval.</li><li><strong>Task Sync &amp; Client Pre-Review Privacy (<code>mobile-video-task-sync</code> AC-10..11):</strong> Uploaded takes link directly to <code>taskId</code> (<code>RAW</code> material) and appear live in Web Task Detail (&#39;Files from Mobile&#39;) for <code>Owner</code>, <code>Manager</code>, and <code>Creator</code>. Before the Task enters <code>CLIENT_REVIEW</code>, <code>Client</code> never sees raw unpromoted takes (<code>url: null</code> / <code>POST_NOT_FOUND</code>); once the assigned <code>Creator</code> promotes the chosen take into the post draft and submits for review, <code>Manager</code> and <code>Client</code> review the exact selected clip.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>camera.*</code>, <code>upload.*</code>, <code>offlineBanner.*</code> in <code>src/i18n/locales/en.json</code> &amp; <code>src/i18n/locales/vi/common.json</code> (<code>tr()</code>)) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/tasks/detail.tsx</code> (&#39;Mobile Uploads&#39; preview &amp; take promotion section)</li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/content/{CameraRecordScreen,CameraUnavailableScreen,TaskUploadScreen,UploadScreen}.tsx</code>, <code>src/components/camera/*</code>, <code>src/components/common/OfflineBanner.tsx</code>, <code>src/services/{mediaSyncService,uploadService}.ts</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;">`POST /api/v1/workspaces/{workspaceId}/materials/upload-session[/multipart</td><td style="text-align:left;">/{id}/parts</td><td style="text-align:left;">/confirm]`</td></tr><tr><td style="text-align:left;"><code>GET/POST /api/v1/workspaces/{workspaceId}/tasks/{taskId}/post</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>; <code>Client</code> gated until review)</td><td style="text-align:left;"><code>TaskPostController</code> -&gt; promotes selected mobile take into Task post draft</td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Upload Session Expired While Underground / Offline:</strong> <code>mediaSyncService.ts</code> detects <code>404/410</code> session expiry on resume, requests a fresh upload session, and completes transfer without user re-selection.</li><li><strong>Permanent Validation Failure (<code>403</code> / unsupported file):</strong> Marks queue item <code>FAILED</code> with exact backend localized error (<code>serverText.ts</code>) without infinite retry loops.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/05-content-task-workflow/README.html">3.6 Content &amp; Workflow — Material Repository &amp; Task Content</a> (<code>3.6.11–3.6.16</code>, <code>3.6.4</code>)</li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/05-content-task-workflow.html">BA 05 Content &amp; Task Workflow</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const g=t(i,[["render",n]]);export{m as __pageData,g as default};
